export const uid=()=>crypto.randomUUID();
export const dateString=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
export const dayOffset=n=>{const d=new Date();d.setDate(d.getDate()+n);return dateString(d);};
export const reviewKeys=['resume','first','second','third','offer'];
export const reviewLabels={resume:'简历筛选',first:'一面',second:'二面',third:'三面',offer:'Offer'};
export const measures={total:'候选人总人数',resumeDone:'已完成简历筛选人数',resumePass:'简历筛选通过人数',firstDone:'已完成一面人数',firstPass:'一面通过人数',secondDone:'已完成二面人数',secondPass:'二面通过人数',thirdDone:'已完成三面人数',thirdPass:'三面通过人数',offerSent:'已发出 Offer 人数',offerAccepted:'接受 Offer 人数',hired:'已入职人数'};
export const defaultMetrics=[{id:'m1',name:'简历通过率',numerator:'resumePass',denominator:'resumeDone'},{id:'m2',name:'一面通过率',numerator:'firstPass',denominator:'firstDone'},{id:'m3',name:'二面通过率',numerator:'secondPass',denominator:'secondDone'},{id:'m4',name:'Offer 接受率',numerator:'offerAccepted',denominator:'offerSent'},{id:'m5',name:'入职率',numerator:'hired',denominator:'offerAccepted'}];
export function countMeasure(rows,key){if(key==='total')return rows.length;if(key==='hired')return rows.filter(c=>c.hiredAt).length;if(key==='offerSent')return rows.filter(c=>['sent','accepted','rejected'].includes(c.reviews?.offer)).length;if(key==='offerAccepted')return rows.filter(c=>c.reviews?.offer==='accepted').length;const m=key.match(/^(resume|first|second|third)(Done|Pass)$/);return m?rows.filter(c=>m[2]==='Done'?['pass','fail'].includes(c.reviews?.[m[1]]):c.reviews?.[m[1]]==='pass').length:0;}
export const percentage=(a,b)=>b?`${(a/b*100).toFixed(1).replace('.0','')}%`:'—';
export function matchingCandidates(rows,c){const phone=String(c.phone||'').replace(/[\s+()-]/g,'');const email=String(c.email||'').trim().toLowerCase();return rows.filter(r=>(phone&&phone===String(r.phone||'').replace(/[\s+()-]/g,''))||(email&&email===String(r.email||'').trim().toLowerCase()));}
export function newCandidate(values={}){const now=new Date().toISOString();return {id:uid(),name:'',phone:'',email:'',jobId:'',stageId:'screen',owner:'林晓',source:'主动投递',city:'',experience:'',education:'',school:'',salary:'',tags:'',notes:'',appliedAt:dateString(),createdAt:now,updatedAt:now,reviews:{resume:'pending',first:'pending',second:'pending',third:'pending',offer:'pending'},hiredAt:null,history:[],...values};}
export function moveCandidate(c,stageId,stages){if(c.stageId===stageId)return;c.history.push({id:uid(),from:c.stageId,to:stageId,at:new Date().toISOString(),note:'切换招聘阶段'});c.stageId=stageId;c.updatedAt=new Date().toISOString();if(stages.find(s=>s.id===stageId)?.kind==='hired')c.hiredAt=c.hiredAt||dateString();}
export function createSeed(){
const stages=[['screen','待筛选'],['schedule','待约面'],['first','一面'],['second','二面'],['third','三面'],['offer','Offer'],['join','待入职'],['hired','已入职'],['rejected','淘汰']].map(([id,name])=>({id,name,kind:id==='hired'?'hired':id==='rejected'?'rejected':'active'}));
const jobs=[['产品与设计','高级产品经理',3,'林晓','上海','P6','25–35K'],['技术研发','前端开发工程师',4,'陈默','上海','P5','20–35K'],['产品与设计','用户体验设计师',2,'林晓','杭州','P5','18–28K'],['技术研发','算法工程师',3,'陈默','北京','P6','30–50K'],['人力资源','HRBP',1,'林晓','上海','P5','18–25K']].map((a,i)=>({id:'job'+i,department:a[0],name:a[1],headcount:a[2],owner:a[3],city:a[4],level:a[5],salary:a[6],publishedAt:dayOffset(-35),deadline:dayOffset(30),status:i===4?'暂停':'招聘中'}));
const names=['许知远','沈安然','周予宁','陈以南','林听禾','陆景行','苏亦舟','江若初','宋时微','顾明川','程书宁','何一然','赵可心','唐予白','吴清和','徐向晚','叶舟','郑予安','韩星野','夏知夏','李思齐','孟言','方知行','白露'];
const candidates=names.map((name,i)=>{const index=[2,1,3,0,5,4,6,0,1,2,7,8,3,0,2,6,7,8,4,1,5,8,2,0][i];const c=newCandidate({id:'candidate'+i,name,jobId:'job'+(i%5),stageId:stages[index].id,owner:i%5===1||i%5===3?'陈默':'林晓',phone:'1990000'+String(i+1000),email:'demo'+i+'@example.com',source:['内推','主动投递','招聘平台'][i%3],city:jobs[i%5].city,experience:String(3+i%7),education:i%3?'本科':'硕士',salary:jobs[i%5].salary,tags:['重点跟进','匹配度高','沟通顺畅'][i%3],notes:'示例候选人，可在此记录沟通情况。',appliedAt:dayOffset(-28+i),hiredAt:index===7?dayOffset(-2):null});const reached=index===8?(i%3===2?0:2):index;for(let n=0;n<reached&&n<7;n++)c.history.push({id:uid(),from:n?stages[n-1].id:null,to:stages[n].id,at:dayOffset(-28+i+n)+'T09:00:00+08:00',note:'示例阶段记录'});c.history.push({id:uid(),from:null,to:c.stageId,at:dayOffset(-1)+'T09:00:00+08:00',note:'示例当前阶段'});['resume','first','second','third'].forEach((k,n)=>{if(index>n+0&&(n===0||index>n+1))c.reviews[k]='pass';});if(index===8){c.reviews.resume=i%3===2?'fail':'pass';c.reviews.first=i%3===2?'pending':'fail';c.reviews.second='pending';c.reviews.third='pending';}c.reviews.offer=index===5?'sent':index===6||index===7?'accepted':'pending';return c;});
const events=[['许知远 · 一面沟通','面试',0,'10:00',0],['沈安然 · 面试时间确认','跟进',0,'14:30',1],['苏亦舟 · 入职资料收集','入职',1,'09:30',6],['林听禾 · Offer 沟通','Offer',2,'15:00',4],['陈以南 · 简历初筛','待办',-1,'16:00',3]].map((a,i)=>({id:'event'+i,title:a[0],type:a[1],date:dayOffset(a[2]),time:a[3],candidateId:candidates[a[4]].id,notes:'示例日程，可点击编辑',done:false}));
return {schemaVersion:1,stages,jobs,candidates,events,assets:[],metrics:[...defaultMetrics,{id:'custom-demo',name:'筛选至入职转化率',numerator:'hired',denominator:'resumeDone',custom:true}]};}
